import { useRef, useMemo } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei/core/OrbitControls";
import { RoundedBox } from "@react-three/drei/core/RoundedBox";
import { Float } from "@react-three/drei/core/Float";
import { ContactShadows } from "@react-three/drei/core/ContactShadows";
import * as THREE from "three";

/* ─── Pastel Material Helpers ─────────────────────────────────────────────── */
const pastel = {
  floor: "#fce4ec",
  wall1: "#fff3e0",
  wall2: "#e8f5e9",
  wall3: "#e3f2fd",
  table: "#ffe0b2",
  tableLeg: "#d7ccc8",
  chair: "#b3e5fc",
  chairLeg: "#90caf9",
  bed: "#f8bbd0",
  bedFrame: "#e1bee7",
  bedBlanket: "#ffffff",
  shelf: "#c8e6c9",
  rug: "#ffe082",
  lamp: "#fff9c4",
  lampPost: "#bcaaa4",
  toy1: "#ef9a9a",
  toy2: "#80cbc4",
  toy3: "#ce93d8",
  toy4: "#ffb74d",
  baby: "#ffccbc",
  babyBody: "#ffab91",
  babyHair: "#8d6e63",
  babyDiaper: "#ffffff",
  wood: "#d7ccc8",
  baseboard: "#ffffff",
  windowFrame: "#ffffff",
  glass: "#e0f7fa",
};

const PM = (color: string, metallic = false, emissive = false) =>
  new THREE.MeshStandardMaterial({
    color,
    roughness: metallic ? 0.3 : 0.85,
    metalness: metallic ? 0.6 : 0.05,
    emissive: emissive ? color : "#000000",
    emissiveIntensity: emissive ? 0.4 : 0,
  });

/* ─── Room Component ──────────────────────────────────────────────────────── */
const Room = () => {
  const materials = useMemo(
    () => ({
      floor: PM(pastel.floor),
      wall1: PM(pastel.wall1),
      wall2: PM(pastel.wall2),
      wall3: PM(pastel.wall3),
      baseboard: PM(pastel.baseboard),
      windowFrame: PM(pastel.windowFrame),
      glass: new THREE.MeshStandardMaterial({
        color: pastel.glass,
        transparent: true,
        opacity: 0.4,
        roughness: 0.1,
        metalness: 0.1,
      }),
    }),
    [],
  );

  return (
    <group>
      {/* Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[10, 10]} />
        <primitive object={materials.floor} attach="material" />
      </mesh>

      {/* Baseboards */}
      <mesh position={[0, 0.05, -3]} receiveShadow castShadow>
        <boxGeometry args={[6, 0.1, 0.05]} />
        <primitive object={materials.baseboard} attach="material" />
      </mesh>
      <mesh
        position={[-3, 0.05, 0]}
        rotation={[0, Math.PI / 2, 0]}
        receiveShadow
        castShadow
      >
        <boxGeometry args={[6, 0.1, 0.05]} />
        <primitive object={materials.baseboard} attach="material" />
      </mesh>
      <mesh
        position={[3, 0.05, 0]}
        rotation={[0, Math.PI / 2, 0]}
        receiveShadow
        castShadow
      >
        <boxGeometry args={[6, 0.1, 0.05]} />
        <primitive object={materials.baseboard} attach="material" />
      </mesh>

      {/* Back Wall */}
      <mesh position={[0, 2, -3]} receiveShadow>
        <planeGeometry args={[6, 4]} />
        <primitive object={materials.wall1} attach="material" />
      </mesh>

      {/* Left Wall with Window Hole */}
      <group position={[-3, 2, 0]} rotation={[0, Math.PI / 2, 0]}>
        <mesh receiveShadow position={[0, -1, 0]}>
          <planeGeometry args={[6, 2]} />
          <primitive object={materials.wall2} attach="material" />
        </mesh>
        <mesh receiveShadow position={[0, 1.5, 0]}>
          <planeGeometry args={[6, 1]} />
          <primitive object={materials.wall2} attach="material" />
        </mesh>
        <mesh receiveShadow position={[-2, 0.5, 0]}>
          <planeGeometry args={[2, 1]} />
          <primitive object={materials.wall2} attach="material" />
        </mesh>
        <mesh receiveShadow position={[2, 0.5, 0]}>
          <planeGeometry args={[2, 1]} />
          <primitive object={materials.wall2} attach="material" />
        </mesh>

        {/* Window Asset */}
        <group position={[0, 0.5, 0]}>
          {/* Frame */}
          <mesh castShadow receiveShadow position={[0, 0, 0.05]}>
            <boxGeometry args={[2.1, 1.1, 0.1]} />
            <primitive object={materials.windowFrame} attach="material" />
          </mesh>
          <mesh castShadow receiveShadow position={[0, 0, 0.05]}>
            <boxGeometry args={[0.1, 1.1, 0.15]} />
            <primitive object={materials.windowFrame} attach="material" />
          </mesh>
          <mesh castShadow receiveShadow position={[0, 0, 0.05]}>
            <boxGeometry args={[2.1, 0.1, 0.15]} />
            <primitive object={materials.windowFrame} attach="material" />
          </mesh>
          {/* Glass panes */}
          <mesh position={[-0.5, 0, 0.05]}>
            <planeGeometry args={[0.9, 0.9]} />
            <primitive object={materials.glass} attach="material" />
          </mesh>
          <mesh position={[0.5, 0, 0.05]}>
            <planeGeometry args={[0.9, 0.9]} />
            <primitive object={materials.glass} attach="material" />
          </mesh>
        </group>
      </group>

      {/* Right Wall */}
      <mesh position={[3, 2, 0]} rotation={[0, -Math.PI / 2, 0]} receiveShadow>
        <planeGeometry args={[6, 4]} />
        <primitive object={materials.wall3} attach="material" />
      </mesh>
    </group>
  );
};

/* ─── Furniture ───────────────────────────────────────────────────────────── */
const Table = () => (
  <group position={[0.5, 0, -1]}>
    {/* Tabletop */}
    <RoundedBox
      args={[1.4, 0.08, 0.8]}
      radius={0.03}
      position={[0, 0.55, 0]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.table} roughness={0.6} />
    </RoundedBox>
    {/* Legs */}
    {[
      [-0.55, 0.275, -0.3],
      [0.55, 0.275, -0.3],
      [-0.55, 0.275, 0.3],
      [0.55, 0.275, 0.3],
    ].map((pos, i) => (
      <RoundedBox
        key={i}
        args={[0.06, 0.55, 0.06]}
        radius={0.02}
        position={pos as [number, number, number]}
        castShadow
        receiveShadow
      >
        <meshStandardMaterial color={pastel.wood} roughness={0.8} />
      </RoundedBox>
    ))}
    {/* Laptop */}
    <group position={[-0.3, 0.6, 0]} rotation={[0, Math.PI / 6, 0]}>
      {/* Base */}
      <RoundedBox
        args={[0.4, 0.02, 0.3]}
        radius={0.005}
        position={[0, 0, 0]}
        castShadow
      >
        <meshStandardMaterial color="#b0bec5" metalness={0.4} roughness={0.4} />
      </RoundedBox>
      {/* Screen */}
      <RoundedBox
        args={[0.4, 0.3, 0.02]}
        radius={0.005}
        position={[0, 0.15, -0.14]}
        rotation={[-Math.PI / 12, 0, 0]}
        castShadow
      >
        <meshStandardMaterial color="#90a4ae" metalness={0.4} roughness={0.4} />
      </RoundedBox>
      <mesh position={[0, 0.15, -0.12]} rotation={[-Math.PI / 12, 0, 0]}>
        <planeGeometry args={[0.36, 0.26]} />
        <meshStandardMaterial
          color="#263238"
          emissive="#1abc9c"
          emissiveIntensity={0.2}
        />
      </mesh>
    </group>
    {/* Coffee Mug */}
    <group position={[0.4, 0.63, 0.1]} rotation={[0, -Math.PI / 4, 0]}>
      <mesh castShadow>
        <cylinderGeometry args={[0.05, 0.05, 0.1, 16]} />
        <meshStandardMaterial color="#ffffff" roughness={0.2} />
      </mesh>
      <mesh position={[0.05, 0, 0]} rotation={[0, 0, -Math.PI / 2]} castShadow>
        <torusGeometry args={[0.03, 0.01, 8, 16, Math.PI]} />
        <meshStandardMaterial color="#ffffff" roughness={0.2} />
      </mesh>
    </group>
  </group>
);

const Chair = () => (
  <group position={[0.5, 0, -0.2]} rotation={[0, Math.PI, 0]}>
    {/* Seat */}
    <RoundedBox
      args={[0.5, 0.06, 0.5]}
      radius={0.02}
      position={[0, 0.35, 0]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.wood} roughness={0.7} />
    </RoundedBox>
    {/* Cushion */}
    <RoundedBox
      args={[0.46, 0.04, 0.46]}
      radius={0.01}
      position={[0, 0.39, 0]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.chair} roughness={0.9} />
    </RoundedBox>
    {/* Back */}
    <RoundedBox
      args={[0.5, 0.45, 0.06]}
      radius={0.02}
      position={[0, 0.6, -0.22]}
      castShadow
    >
      <meshStandardMaterial color={pastel.wood} roughness={0.7} />
    </RoundedBox>
    {/* Legs */}
    {[
      [-0.2, 0.175, -0.2],
      [0.2, 0.175, -0.2],
      [-0.2, 0.175, 0.2],
      [0.2, 0.175, 0.2],
    ].map((pos, i) => (
      <mesh key={i} position={pos as [number, number, number]} castShadow>
        <cylinderGeometry args={[0.02, 0.02, 0.35, 8]} />
        <meshStandardMaterial color={pastel.wood} roughness={0.8} />
      </mesh>
    ))}
  </group>
);

const Bed = () => (
  <group position={[-1.7, 0, -1.8]}>
    {/* Headboard */}
    <RoundedBox
      args={[1.6, 0.8, 0.1]}
      radius={0.03}
      position={[0, 0.4, -0.95]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.bedFrame} roughness={0.8} />
    </RoundedBox>
    {/* Frame */}
    <RoundedBox
      args={[1.5, 0.35, 2]}
      radius={0.05}
      position={[0, 0.175, 0]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.wood} roughness={0.8} />
    </RoundedBox>
    {/* Mattress */}
    <RoundedBox
      args={[1.3, 0.15, 1.8]}
      radius={0.06}
      position={[0, 0.425, 0]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.bed} roughness={0.9} />
    </RoundedBox>
    {/* Blanket */}
    <RoundedBox
      args={[1.34, 0.16, 1.2]}
      radius={0.06}
      position={[0, 0.43, 0.3]}
      castShadow
      receiveShadow
    >
      <meshStandardMaterial color={pastel.bedBlanket} roughness={0.9} />
    </RoundedBox>
    {/* Pillow 1 */}
    <RoundedBox
      args={[0.5, 0.12, 0.3]}
      radius={0.05}
      position={[-0.3, 0.55, -0.65]}
      rotation={[0.1, 0, 0]}
      castShadow
    >
      <meshStandardMaterial color="#ffffff" roughness={0.95} />
    </RoundedBox>
    {/* Pillow 2 */}
    <RoundedBox
      args={[0.5, 0.12, 0.3]}
      radius={0.05}
      position={[0.3, 0.53, -0.6]}
      rotation={[0.05, 0.1, -0.05]}
      castShadow
    >
      <meshStandardMaterial color={pastel.chair} roughness={0.95} />
    </RoundedBox>

    {/* Nightstand */}
    <group position={[-1.1, 0, -0.7]}>
      <RoundedBox
        args={[0.5, 0.4, 0.4]}
        radius={0.02}
        position={[0, 0.2, 0]}
        castShadow
        receiveShadow
      >
        <meshStandardMaterial color={pastel.wood} roughness={0.8} />
      </RoundedBox>
      <RoundedBox
        args={[0.4, 0.15, 0.05]}
        radius={0.01}
        position={[0, 0.25, 0.2]}
        castShadow
      >
        <meshStandardMaterial color={pastel.bedFrame} roughness={0.8} />
      </RoundedBox>
      <mesh position={[0, 0.25, 0.23]} castShadow>
        <sphereGeometry args={[0.03, 8, 8]} />
        <meshStandardMaterial color="#90a4ae" metalness={0.5} roughness={0.5} />
      </mesh>
      {/* Clock */}
      <group position={[0, 0.45, 0]} rotation={[0, Math.PI / 4, 0]}>
        <mesh castShadow>
          <boxGeometry args={[0.15, 0.1, 0.05]} />
          <meshStandardMaterial color="#ef5350" roughness={0.3} />
        </mesh>
        <mesh position={[0, 0, 0.026]}>
          <planeGeometry args={[0.12, 0.07]} />
          <meshStandardMaterial color="#212121" />
        </mesh>
      </group>
    </group>
  </group>
);

const Shelf = () => (
  <group position={[-2.8, 0.8, 1.5]}>
    {/* Shelves */}
    {[0, 0.5, 1.0].map((y, i) => (
      <RoundedBox
        key={i}
        args={[0.3, 0.04, 0.8]}
        radius={0.01}
        position={[0, y, 0]}
        castShadow
        receiveShadow
      >
