    const t = state.clock.elapsedTime;

    // Gentle bobbing and looking around
    ref.current.position.y = 0.25 + Math.sin(t * 1.5) * 0.015;
    headRef.current.rotation.y = Math.sin(t * 0.8) * 0.3;
