    leftArmRef.current.rotation.x = -Math.PI / 6 + Math.cos(t * 2) * 0.2;
    rightArmRef.current.rotation.z = -Math.PI / 4 + Math.sin(t * 3.2) * 0.2;
    rightArmRef.current.rotation.x = -Math.PI / 6 + Math.cos(t * 2.2) * 0.2;
