/**
 * BabyCharacter — Animated toddler actor using walk_animated.glb.
 *
 * Calibrated values:
 *   raw size: 2.857 × 3.077 × 6.572
 *   scale   : 0.162496  → world H ≈ 0.5 units
 *   floorY  : 0.2164    → lifts raw minY (-1.332) to world y=0
 *
 * Available animations (all in walk_animated.glb):
 *   'play_toys'  — baby sitting, playing with toys  (scroll 0.28–0.39)
 *   'stand_up'   — baby rises to standing           (scroll 0.39–0.54)
 *   'walk'       — walking cycle                    (scroll 0.54–0.80)
 *
 * Baby also moves toward the hazard table during the walk phase.
 */
import { useRef, useEffect } from "react";
import { useGLTF, useAnimations } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

const SCALE = 0.162496;
const FLOOR_Y = 0.2164;

/* Start/end world positions for the walk journey */
const WALK_START: [number, number, number] = [0, 0, 0.5];
const WALK_END: [number, number, number] = [0.75, 0, -0.25];

interface Props {
  scrollProgress: number;
  position?: [number, number, number];
}

export default function BabyCharacter({
  scrollProgress,
  position = [0, 0, 0],
}: Props) {
  const groupRef = useRef<THREE.Group>(null!);
  const { scene, animations } = useGLTF("/models/walk_animated.glb");
  const { actions } = useAnimations(animations, groupRef);

  /* Track which animation is currently playing */
  const currentAnim = useRef<string>("");

  /* ── Animation state machine ────────────────────────── */
  useEffect(() => {
    let target = "play_toys";
    if (scrollProgress >= 0.39 && scrollProgress < 0.54) target = "stand_up";
    else if (scrollProgress >= 0.54) target = "walk";

    if (target === currentAnim.current) return;
    currentAnim.current = target;

    const next = actions[target];
    if (!next) return;

    /* Cross-fade out all other actions */
    Object.entries(actions).forEach(([name, a]) => {
      if (name !== target && a && a.isRunning()) {
        a.fadeOut(0.4);
      }
    });

    next.reset().fadeIn(0.4).play();

    /* stand_up plays once (not looped) */
    if (target === "stand_up") {
      next.setLoop(THREE.LoopOnce, 1);
      next.clampWhenFinished = true;
    } else {
      next.setLoop(THREE.LoopRepeat, Infinity);
    }
  }, [scrollProgress, actions]);

  /* ── World position & facing direction ──────────────── */
  const worldPos = useRef(new THREE.Vector3(...WALK_START));
  const targetPos = useRef(new THREE.Vector3(...WALK_START));
  const targetRotY = useRef(0);

  useEffect(() => {
    if (scrollProgress < 0.54) {
      targetPos.current.set(...WALK_START);
      targetRotY.current = 0;
    } else {
      /* Walk progress: 0→1 between scroll 0.54 and 0.78 */
      const wp = Math.min(1, (scrollProgress - 0.54) / 0.24);
      targetPos.current.set(
        WALK_START[0] + (WALK_END[0] - WALK_START[0]) * wp,
        0,
        WALK_START[2] + (WALK_END[2] - WALK_START[2]) * wp,
      );
      /* Rotate to face walk direction */
      const dx = WALK_END[0] - WALK_START[0];
      const dz = WALK_END[2] - WALK_START[2];
      targetRotY.current = Math.atan2(dx, dz);
    }
  }, [scrollProgress]);

  useFrame(() => {
    if (!groupRef.current) return;
    worldPos.current.lerp(targetPos.current, 0.05);
    groupRef.current.position.set(
      position[0] + worldPos.current.x,
      position[1] + FLOOR_Y,
      position[2] + worldPos.current.z,
    );
    groupRef.current.rotation.y +=
      (targetRotY.current - groupRef.current.rotation.y) * 0.06;
  });

  /* ── Visibility: only shown from Wonderland phase on ── */
  const visible = scrollProgress > 0.26;

  return (
    <group ref={groupRef} scale={SCALE} visible={visible}>
      <primitive object={scene} />
    </group>
  );
}

useGLTF.preload("/models/walk_animated.glb");

/**
 * AudioEngine — Scroll-triggered Web Audio manager.
 * Plays ambient sound effects as the user scrolls through the journey.
 */
import { useEffect, useRef, useCallback } from 'react';

interface AudioRef {
  ctx: AudioContext | null;
  buffers: Record<string, AudioBuffer>;
  sources: Record<string, { source: AudioBufferSourceNode; gain: GainNode } | null>;
}

const SOUND_FILES: Record<string, string> = {
  toys: '/sounds/toys_clack.wav',
  heartbeat: '/sounds/heartbeat_pulse.wav',
  shimmer: '/sounds/shimmer_magic.wav',
};

/* Scroll thresholds: at which scroll % each sound kicks in/out */
const TRIGGERS = {
  toys: { start: 0.0, end: 0.30 },
  heartbeat: { start: 0.30, end: 0.60 },
  shimmer: { start: 0.55, end: 0.85 },
};

export default function AudioEngine({ scrollProgress }: { scrollProgress: number }) {
  const ref = useRef<AudioRef>({ ctx: null, buffers: {}, sources: {} });
  const loaded = useRef(false);

  /* ── Bootstrap AudioContext + preload buffers ─────────── */
  const init = useCallback(async () => {
    if (loaded.current) return;
    loaded.current = true;

    const ctx = new AudioContext();
    ref.current.ctx = ctx;

    await Promise.all(
      Object.entries(SOUND_FILES).map(async ([key, url]) => {
        try {
          const res = await fetch(url);
          const buf = await res.arrayBuffer();
          ref.current.buffers[key] = await ctx.decodeAudioData(buf);
        } catch {
          console.warn(`[AudioEngine] Could not load ${url}`);
        }
      }),
    );
  }, []);

  /* Resume context on first user interaction */
  useEffect(() => {
    const resume = () => {
      init();
      if (ref.current.ctx?.state === 'suspended') ref.current.ctx.resume();
    };
    window.addEventListener('pointerdown', resume, { once: true });
    window.addEventListener('wheel', resume, { once: true });
    return () => {
      window.removeEventListener('pointerdown', resume);
      window.removeEventListener('wheel', resume);
    };
  }, [init]);

  /* ── Play / stop helpers ──────────────────────────────── */
  const play = useCallback((key: string, volume = 0.25) => {
    const { ctx, buffers, sources } = ref.current;
    if (!ctx || !buffers[key] || sources[key]) return;

    const source = ctx.createBufferSource();
    const gain = ctx.createGain();
    source.buffer = buffers[key];
    source.loop = true;
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + 0.8);
    source.connect(gain).connect(ctx.destination);
    source.start();
    sources[key] = { source, gain };
  }, []);

  const stop = useCallback((key: string) => {
    const { ctx, sources } = ref.current;
    if (!ctx || !sources[key]) return;
    const { source, gain } = sources[key]!;
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.6);
    setTimeout(() => { try { source.stop(); } catch { /* noop */ } }, 700);
    sources[key] = null;
  }, []);

  /* ── React to scroll progress ─────────────────────────── */
  useEffect(() => {
    Object.entries(TRIGGERS).forEach(([key, { start, end }]) => {
      const inRange = scrollProgress >= start && scrollProgress <= end;
      if (inRange) play(key, 0.18);
      else stop(key);
    });
  }, [scrollProgress, play, stop]);

  /* Cleanup on unmount */
  useEffect(() => {
    return () => {
      Object.keys(ref.current.sources).forEach(stop);
      ref.current.ctx?.close();
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return null; // no DOM
}

