/**
 * GuardianParticles — Mint-colored AI guardian particle shield.
 * Spawns between the baby and the hazard table as `progress` goes 0→1.
 * Particles form an arc/barrier, then swirl and dissolve.
 */
import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

const COUNT = 320;

interface Props {
  progress: number; // 0→1
  position?: [number, number, number];
}

export default function GuardianParticles({
  progress,
  position = [0.4, 0.3, 0.1],
}: Props) {
  const pointsRef = useRef<THREE.Points>(null!);

  /* Each particle: seed positions on a shield arc + random offsets */
  const { seeds, phases, speeds } = useMemo(() => {
    const s = new Float32Array(COUNT * 3);
    const p = new Float32Array(COUNT);
    const v = new Float32Array(COUNT);

    for (let i = 0; i < COUNT; i++) {
      const t = i / COUNT;
      /* Arc: semi-circle in XZ plane, between baby (z=0.5) and table (z=-0.3) */
      const angle = -Math.PI * 0.6 + t * Math.PI * 1.2;
      const r = 0.25 + Math.random() * 0.18;
      s[i * 3] = Math.cos(angle) * r;
      s[i * 3 + 1] = Math.random() * 0.55; // height 0–0.55
      s[i * 3 + 2] = Math.sin(angle) * r * 0.6; // slightly flat arc
      p[i] = Math.random() * Math.PI * 2; // phase offset
      v[i] = 0.6 + Math.random() * 1.2; // drift speed
    }
    return { seeds: s, phases: p, speeds: v };
  }, []);

  const positions = useMemo(() => new Float32Array(COUNT * 3), []);

  useFrame(({ clock }) => {
    if (!pointsRef.current) return;
    if (progress <= 0.01) {
      pointsRef.current.visible = false;
      return;
    }
    pointsRef.current.visible = true;

    const t = clock.getElapsedTime();
    const attr = pointsRef.current.geometry.attributes.position;
    const pos = attr.array as Float32Array;

    for (let i = 0; i < COUNT; i++) {
      /* Spawn delay: particles appear one by one */
      const spawnThreshold = i / COUNT;
      const localP = Math.max(
        0,
        (progress - spawnThreshold) / (1 - spawnThreshold + 0.001),
      );
      const alive = localP > 0;

      if (!alive) {
        pos[i * 3] = seeds[i * 3];
        pos[i * 3 + 1] = -10; // below ground (invisible)
        pos[i * 3 + 2] = seeds[i * 3 + 2];
        continue;
      }

      const drift = t * speeds[i];
      pos[i * 3] = seeds[i * 3] + Math.sin(drift + phases[i]) * 0.06;
      pos[i * 3 + 1] =
        seeds[i * 3 + 1] +
        Math.sin(drift * 0.7 + phases[i] + 1) * 0.04 +
        localP * 0.1; // slow upward float
      pos[i * 3 + 2] = seeds[i * 3 + 2] + Math.cos(drift + phases[i]) * 0.04;
    }

    attr.needsUpdate = true;

    /* Fade material with progress */
    const mat = pointsRef.current.material as THREE.PointsMaterial;
    const shimmer = 0.6 + 0.4 * Math.sin(t * 3.5);
    mat.opacity = Math.min(1, progress * 3) * 0.75 * shimmer;
  });

  /* Initial buffer */
  for (let i = 0; i < COUNT; i++) {
    positions[i * 3] = seeds[i * 3];
    positions[i * 3 + 1] = seeds[i * 3 + 1];
    positions[i * 3 + 2] = seeds[i * 3 + 2];
  }

  return (
    <group position={position}>
      <points ref={pointsRef}>
        <bufferGeometry>
          <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        </bufferGeometry>
        <pointsMaterial
          size={0.022}
          color="#78dcd2"
          transparent
          opacity={0}
          sizeAttenuation
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </points>

      {/* Ambient glow light that strengthens with progress */}
      <pointLight
        position={[0, 0.3, 0]}
        intensity={progress * 0.6}
        color="#78dcd2"
        distance={2.5}
        decay={2}
      />
    </group>
  );
}

