/**
 * HouseComplete — Loads house_complete.glb (exterior + interior in one model).
 *
 * Calibrated values from ModelDiagnostic:
 *   raw size: 294.16 × 231.23 × 223.28
 *   scale   : 0.015137  → world H ≈ 3.5 units
 *   floorY  : 0.1317    → lifts raw minY (-8.698) to world y=0
 *
 * Node map (key names):
 *   exterior_wall  — outer wall mesh (animated by 'exterior_wallAction')
 *   exterior_roof  — roof
 *   chimney        — chimney
 *   window_glass   — windows (emissive glow when lit)
 *   Interior:      Couch, Table, Rug, Curtains, Paintings, TvStand, etc.
 *
 * Strategy:
 *   scroll < 0.26  → exterior fully visible; window glass emits warm glow
 *   scroll 0.26+   → exterior_wall fades away (triggers animation), interior revealed
 */
import { useEffect, useRef } from "react";
import { useGLTF, useAnimations } from "@react-three/drei";
import * as THREE from "three";

const HOUSE_SCALE = 0.015137;
const HOUSE_FLOOR_Y = 0.1317; // world y offset so ground = 0

interface Props {
  scrollProgress: number;
}

export default function HouseComplete({ scrollProgress }: Props) {
  const groupRef = useRef<THREE.Group>(null!);
  const { scene, animations } = useGLTF("/models/house_complete.glb");
  const { actions } = useAnimations(animations, groupRef);

  /* ── One-time setup after model loads ────────────────── */
  useEffect(() => {
    if (!scene) return;

    scene.traverse((child) => {
      if (!(child as THREE.Mesh).isMesh) return;
      const mesh = child as THREE.Mesh;
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      // Window glass: warm emissive amber for "light inside" look
      if (child.name === "window_glass") {
        const mats = Array.isArray(mesh.material)
          ? mesh.material
          : [mesh.material];
        mats.forEach((m) => {
          if (m instanceof THREE.MeshStandardMaterial) {
            m.emissive = new THREE.Color("#ffe4a0");
            m.emissiveIntensity = 1.8;
            m.transparent = true;
            m.opacity = 0.6;
          }
        });
      }
    });
  }, [scene]);

  /* ── Trigger exterior-wall animation when entering house ─ */
  const wallRevealDone = useRef(false);

  useEffect(() => {
    if (scrollProgress > 0.25 && !wallRevealDone.current) {
      wallRevealDone.current = true;
      const action = actions["exterior_wallAction"];
      if (action) {
        action.setLoop(THREE.LoopOnce, 1);
        action.clampWhenFinished = true;
        action.reset().play();
      }
    }
  }, [scrollProgress, actions]);

  /* ── Fade exterior wall transparency when camera inside ─ */
  useEffect(() => {
    if (!scene) return;

    const fadeStart = 0.24;
    const fadeEnd = 0.3;
    const alpha =
      scrollProgress < fadeStart
        ? 1.0
        : scrollProgress > fadeEnd
          ? 0.0
          : 1.0 - (scrollProgress - fadeStart) / (fadeEnd - fadeStart);

    scene.traverse((child) => {
      if (!(child as THREE.Mesh).isMesh) return;
      const n = child.name;
      if (n === "exterior_wall" || n === "chimney") {
        const mesh = child as THREE.Mesh;
        const mats = Array.isArray(mesh.material)
          ? mesh.material
          : [mesh.material];
        mats.forEach((m) => {
          if (m instanceof THREE.Material) {
            m.transparent = true;
            m.opacity = alpha;
            // Hide completely when inside to save draw calls
            mesh.visible = alpha > 0.02;
          }
        });
      }
    });
  }, [scrollProgress, scene]);

  return (
    <group ref={groupRef} position={[0, HOUSE_FLOOR_Y, 0]} scale={HOUSE_SCALE}>
      <primitive object={scene} />
    </group>
  );
}

