/**
 * StarrySky — Disney 80-90s style night sky.
 * Features: twinkling star field, animated moon with honey glow, shooting stars.
 * Fades out gracefully as camera descends into the house (scroll > 0.20).
 */
import { useRef, useMemo, useEffect } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

/* ── Twinkling Stars ───────────────────────────────────── */
function StarField({ opacity }: { opacity: number }) {
  const COUNT = 1800;
  const pointsRef = useRef<THREE.Points>(null!);

  const { positions, sizes } = useMemo(() => {
    const pos = new Float32Array(COUNT * 3);
    const sz = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1) * 0.48; // upper hemisphere
      const r = 60 + Math.random() * 20;
      pos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      pos[i * 3 + 1] = Math.abs(r * Math.cos(phi)) + 2; // all above horizon
      pos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
      sz[i] = 0.6 + Math.random() * 2.4;
    }
    return { positions: pos, sizes: sz };
  }, []);

  const phaseOffsets = useMemo(() => {
    const arr = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) arr[i] = Math.random() * Math.PI * 2;
    return arr;
  }, []);

  useFrame(({ clock }) => {
    if (!pointsRef.current) return;
    const mat = pointsRef.current.material as THREE.PointsMaterial;
    const t = clock.getElapsedTime();
    // Modulate opacity with sin waves for twinkle
    const twinkle = 0.55 + 0.45 * Math.sin(t * 1.3 + phaseOffsets[0]);
    mat.opacity = opacity * twinkle;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-size" args={[sizes, 1]} />
      </bufferGeometry>
      <pointsMaterial
        size={0.18}
        color="#fffde8"
        transparent
        opacity={opacity}
        sizeAttenuation
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

/* ── Moon ─────────────────────────────────────────────── */
function Moon({ opacity }: { opacity: number }) {
  const moonRef = useRef<THREE.Mesh>(null!);
  const glowRef = useRef<THREE.Mesh>(null!);

  useFrame(({ clock }) => {
    if (!moonRef.current) return;
    const pulse = 1.0 + 0.04 * Math.sin(clock.getElapsedTime() * 0.7);
    if (glowRef.current) {
      (glowRef.current.material as THREE.MeshBasicMaterial).opacity =
        opacity * 0.22 * pulse;
    }
    (moonRef.current.material as THREE.MeshBasicMaterial).opacity = opacity;
  });

  return (
    <group position={[-18, 38, -55]}>
      {/* Outer glow halo */}
      <mesh ref={glowRef}>
        <sphereGeometry args={[6.5, 32, 32]} />
        <meshBasicMaterial
          color="#ffe88c"
          transparent
          opacity={0.18}
          side={THREE.BackSide}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
      {/* Mid glow */}
      <mesh>
        <sphereGeometry args={[5.0, 32, 32]} />
        <meshBasicMaterial
          color="#fff2b0"
          transparent
          opacity={0.12 * opacity}
          side={THREE.BackSide}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </mesh>
      {/* Moon body */}
      <mesh ref={moonRef}>
        <sphereGeometry args={[3.6, 48, 48]} />
        <meshBasicMaterial color="#fff8d8" transparent opacity={opacity} />
      </mesh>
      {/* Disney detail: subtle crater shading */}
      <mesh position={[1.2, 0.8, 3.4]}>
        <sphereGeometry args={[0.45, 16, 16]} />
        <meshBasicMaterial
          color="#ede0b0"
          transparent
          opacity={0.4 * opacity}
        />
      </mesh>
      <mesh position={[-1.0, -0.5, 3.4]}>
        <sphereGeometry args={[0.3, 16, 16]} />
        <meshBasicMaterial
          color="#ede0b0"
          transparent
          opacity={0.3 * opacity}
        />
      </mesh>
    </group>
  );
}

/* ── Shooting Stars ───────────────────────────────────── */
interface ShootingStarState {
  active: boolean;
  progress: number;
  speed: number;
  startX: number;
  startY: number;
  startZ: number;
  dirX: number;
  dirY: number;
  dirZ: number;
  nextAt: number;
}

function ShootingStars({ opacity }: { opacity: number }) {
  const POOL = 3;
  const meshRefs = useRef<(THREE.Mesh | null)[]>(Array(POOL).fill(null));

  const stars = useRef<ShootingStarState[]>(
    Array.from({ length: POOL }, (_, i) => ({
      active: false,
      progress: 0,
      speed: 0.7 + Math.random() * 0.8,
      startX: 0,
      startY: 0,
      startZ: 0,
      dirX: 0,
      dirY: 0,
      dirZ: 0,
      nextAt: i * 2.5 + Math.random() * 3,
    })),
  );

  const resetStar = (s: ShootingStarState) => {
    s.active = true;
    s.progress = 0;
    s.speed = 0.5 + Math.random() * 0.9;
    // Start high in the sky
    s.startX = (Math.random() - 0.5) * 80;
    s.startY = 25 + Math.random() * 25;
    s.startZ = -40 - Math.random() * 20;
    // Streak diagonally downward
    s.dirX = 15 + Math.random() * 20;
    s.dirY = -8 - Math.random() * 10;
    s.dirZ = 8 + Math.random() * 10;
  };

  useFrame(({ clock }, delta) => {
    if (opacity <= 0.01) return;

    const t = clock.getElapsedTime();
    stars.current.forEach((s, i) => {
      const mesh = meshRefs.current[i];
      if (!mesh) return;

      if (!s.active) {
        mesh.visible = false;
        if (t > s.nextAt) resetStar(s);
        return;
      }

      s.progress += delta * s.speed;

      if (s.progress > 1.2) {
        s.active = false;
        mesh.visible = false;
        s.nextAt = t + 4 + Math.random() * 6;
        return;
      }

      const p = Math.max(0, Math.min(1, s.progress));
      mesh.visible = true;
      mesh.position.set(
        s.startX + s.dirX * p,
        s.startY + s.dirY * p,
        s.startZ + s.dirZ * p,
      );

      // Fade in quickly, fade out at end
      const alpha = p < 0.1 ? p / 0.1 : p > 0.7 ? 1 - (p - 0.7) / 0.3 : 1;
      const mat = mesh.material as THREE.MeshBasicMaterial;
      mat.opacity = opacity * alpha * 0.95;

      // Rotate to face direction of travel
      mesh.rotation.z = Math.atan2(s.dirY, s.dirX);
    });
  });

  return (
    <>
      {Array.from({ length: POOL }, (_, i) => (
        <mesh
          key={i}
          ref={(r) => {
            meshRefs.current[i] = r;
          }}
          visible={false}
        >
          {/* Elongated streak */}
          <capsuleGeometry args={[0.04, 3.5, 4, 8]} />
          <meshBasicMaterial
            color="#fffad0"
            transparent
            opacity={0}
            blending={THREE.AdditiveBlending}
            depthWrite={false}
          />
        </mesh>
      ))}
    </>
  );
}

/* ── Master Sky Controller ────────────────────────────── */
interface Props {
  scrollProgress: number;
}

export default function StarrySky({ scrollProgress }: Props) {
  /* Fade out sky as camera descends below scroll=0.22 */
  const skyOpacity =
    scrollProgress < 0.14
      ? 1.0
      : scrollProgress < 0.28
        ? 1.0 - (scrollProgress - 0.14) / 0.14
        : 0.0;

  if (skyOpacity <= 0.01) return null;

  return (
    <group>
      <StarField opacity={skyOpacity} />
      <Moon opacity={skyOpacity} />
      <ShootingStars opacity={skyOpacity} />
      {/* Horizon gradient glow — deep navy to give depth */}
      <mesh position={[0, -5, -70]} rotation={[Math.PI / 2, 0, 0]}>
        <planeGeometry args={[200, 30]} />
        <meshBasicMaterial
          color="#05091a"
          transparent
          opacity={0.7 * skyOpacity}
          depthWrite={false}
        />
      </mesh>
    </group>
  );
}

