/**
 * JourneyScene — Master orchestrator for "The Safe Steps Journey"
 *
 * Phase 0 (0.00–0.14): STARRY NIGHT — Camera looks UP at stars, moon, shooting stars
 * Phase 0→1 (0.14–0.28): DESCENT — Camera tilts down, house exterior revealed
 * Phase 1 (0.28–0.39): WONDERLAND — Inside room, god-ray, baby plays with toys
 * Phase 2 (0.39–0.54): FIRST STEPS — Baby stands up and walks
 * Phase 3 (0.54–0.78): GUARDIAN — Mint particles form shield, danger neutralized
 * Phase 4 (0.80–1.00): BLUEPRINT — Bird's-eye + CTA overlay
 *
 * All model scales calibrated from ModelDiagnostic bounding box data.
 */
import { Suspense, useState, useEffect, useCallback, useRef } from "react";
import { Canvas } from "@react-three/fiber";
import * as THREE from "three";

/* Sub-components */
import CameraManager from "./CameraManager";
import PostProcessingEffects from "./PostProcessingEffects";
import HouseComplete from "./Environment/HouseComplete";
import StarrySky from "./Environment/StarrySky";
import BabyCharacter from "./Actors/BabyCharacter";
import Toys from "./Actors/Toys";
import HazardTable from "./Actors/HazardTable";
import GuardianParticles from "./Effects/GuardianParticles";
import AudioEngine from "./AudioEngine";
import BlueprintOverlay from "./BlueprintOverlay";
import PixieDustCursor from "./Effects/PixieDustCursor";
import StoryOverlay from "./StoryOverlay";

/* ── Dust Motes (floating in god rays) ────────────────── */
function DustMotes({ visible }: { visible: boolean }) {
  const count = 100;
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    positions[i * 3] = (Math.random() - 0.5) * 4;
    positions[i * 3 + 1] = Math.random() * 2.5;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 4;
  }

  return (
    <points visible={visible}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={0.01}
        color="#fff5e0"
        transparent
        opacity={0.22}
        sizeAttenuation
        depthWrite={false}
      />
    </points>
  );
}

/* ── Scene Lighting ────────────────────────────────────── */
function SceneLighting({ scrollProgress }: { scrollProgress: number }) {
  const isInside = scrollProgress > 0.26;
  const isBluePrint = scrollProgress > 0.8;

  const ambientInt = !isInside
    ? 0.04 + scrollProgress * 0.15 // very dark outside → gradually lighter
    : isBluePrint
      ? 0.55
      : 0.35 + (scrollProgress - 0.26) * 0.4;

  const keyColor = isBluePrint
    ? new THREE.Color("#a0c4ff")
    : new THREE.Color("#ffe4b5");

  const keyInt = isInside ? 0.55 + scrollProgress * 0.2 : 0.08;

  return (
    <>
      <ambientLight intensity={ambientInt} color="#fff5ee" />

      {/* Key light */}
      <directionalLight
        position={[3, 5, 2]}
        intensity={keyInt}
        color={keyColor}
        castShadow
        shadow-mapSize-width={1024}
        shadow-mapSize-height={1024}
        shadow-bias={-0.001}
      />

      {/* Fill light */}
      <directionalLight
        position={[-3, 3, -2]}
        intensity={isInside ? 0.12 : 0.04}
        color="#e8d5ff"
      />

      {/* Baby spotlight — only when inside */}
      <pointLight
        position={[0, 1.8, 0.5]}
        intensity={isInside ? 0.65 : 0}
        color="#ffcc88"
        distance={5}
        decay={2}
      />

      {/* Window god-ray */}
      <spotLight
        position={[2.8, 3.5, 1.8]}
        angle={0.38}
        penumbra={0.85}
        intensity={isInside ? 1.1 : 0}
        color="#fff8e7"
        castShadow
      />

      {/* Blueprint overhead */}
      {isBluePrint && (
        <pointLight
          position={[0, 5, 0]}
          intensity={0.8}
          color="#78dcd2"
          distance={12}
          decay={2}
        />
      )}
    </>
  );
}

/* ── Fog ───────────────────────────────────────────────── */
function FogController({ scrollProgress }: { scrollProgress: number }) {
  const isInside = scrollProgress > 0.26;
  const near = isInside
    ? 0.5 + scrollProgress * 8
    : scrollProgress < 0.14
      ? 40
      : 8;
  const far = isInside
    ? 4 + scrollProgress * 20
    : scrollProgress < 0.14
      ? 90
      : 30;
  const color =
    scrollProgress < 0.14
      ? "#050818" // Deep navy: starry sky
      : scrollProgress < 0.26
        ? "#080c1c" // Transition: dark purple-blue
        : "#16131e"; // Indoor: warm dark

  return <fog attach="fog" args={[color, near, far]} />;
}

/* ── Ground Plane ──────────────────────────────────────── */
function Ground() {
  return (
    <mesh
      rotation={[-Math.PI / 2, 0, 0]}
      position={[0, -0.01, 0]}
      receiveShadow
    >
      <planeGeometry args={[120, 120]} />
      <meshStandardMaterial color="#0e2418" roughness={0.92} metalness={0} />
    </mesh>
  );
}

/* ── Loading Screen ────────────────────────────────────── */
function Loader() {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#050818",
        zIndex: 100,
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 18,
        }}
      >
        <div
          style={{
            width: 48,
            height: 48,
            border: "2px solid rgba(255,228,160,0.12)",
            borderTopColor: "#ffe4a0",
            borderRadius: "50%",
            animation: "spin 1s linear infinite",
          }}
        />
        <span
          style={{
            fontFamily: "'Cinzel Decorative', serif",
            fontSize: 13,
            letterSpacing: "0.14em",
            color: "rgba(255,248,230,0.55)",
          }}
        >
          Once upon a time...
        </span>
      </div>
    </div>
  );
}

/* ── Phase / Progress HUD ─────────────────────────────── */
function ScrollHUD({ progress }: { progress: number }) {
  const phases = [
    { label: "Starlight", range: [0.0, 0.14] },
    { label: "Descent", range: [0.14, 0.28] },
    { label: "Wonderland", range: [0.28, 0.39] },
    { label: "First Steps", range: [0.39, 0.54] },
    { label: "Guardian", range: [0.54, 0.8] },
    { label: "Blueprint", range: [0.8, 1.0] },
  ];

  const active =
    phases.find((p) => progress >= p.range[0] && progress <= p.range[1]) ||
    phases[0];

  return (
    <div
      style={{
        position: "fixed",
        bottom: 28,
        left: "50%",
        transform: "translateX(-50%)",
        zIndex: 55,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 10,
        pointerEvents: "none",
      }}
    >
      <div
        style={{
          padding: "5px 18px",
          borderRadius: 999,
          background: "rgba(0,0,0,0.5)",
          backdropFilter: "blur(10px)",
          border: "1px solid rgba(255,228,160,0.10)",
          fontFamily: "'Cormorant Garamond', serif",
          color: "rgba(255,228,160,0.75)",
          fontSize: 12,
          fontWeight: 600,
          letterSpacing: "0.12em",
        }}
      >
        {active.label}
      </div>
      <div
        style={{
          width: 180,
          height: 2,
          borderRadius: 4,
          background: "rgba(255,255,255,0.05)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${progress * 100}%`,
            height: "100%",
            borderRadius: 4,
            background: "linear-gradient(90deg, #ffe4a0, #78dcd2)",
            transition: "width 0.12s ease-out",
          }}
        />
      </div>
      {progress < 0.04 && (
        <div
          style={{
            fontFamily: "'Cormorant Garamond', serif",
            color: "rgba(255,248,230,0.3)",
            fontSize: 11,
            fontStyle: "italic",
            animation: "pulse 2.2s ease-in-out infinite",
          }}
        >
          ↓ Scroll to begin the journey
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   MAIN EXPORTED COMPONENT
   ════════════════════════════════════════════════════════ */
export default function JourneyScene() {
  const [scrollProgress, setScrollProgress] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef(0);
  const SCROLL_PAGES = 7; // more pages = slower, more cinematic

  /* Wheel + touch scroll handlers */
  const handleWheel = useCallback((e: WheelEvent) => {
    e.preventDefault();
    const delta = e.deltaY / (window.innerHeight * SCROLL_PAGES);
    scrollRef.current = Math.max(0, Math.min(1, scrollRef.current + delta));
    setScrollProgress(scrollRef.current);
  }, []);

  const touchStartY = useRef(0);
  const handleTouchStart = useCallback((e: TouchEvent) => {
    touchStartY.current = e.touches[0].clientY;
  }, []);
  const handleTouchMove = useCallback((e: TouchEvent) => {
    e.preventDefault();
    const dy = touchStartY.current - e.touches[0].clientY;
    touchStartY.current = e.touches[0].clientY;
    const delta = dy / (window.innerHeight * SCROLL_PAGES);
    scrollRef.current = Math.max(0, Math.min(1, scrollRef.current + delta));
    setScrollProgress(scrollRef.current);
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    el.addEventListener("wheel", handleWheel, { passive: false });
    el.addEventListener("touchstart", handleTouchStart, { passive: true });
    el.addEventListener("touchmove", handleTouchMove, { passive: false });
    return () => {
      el.removeEventListener("wheel", handleWheel);
      el.removeEventListener("touchstart", handleTouchStart);
      el.removeEventListener("touchmove", handleTouchMove);
    };
  }, [handleWheel, handleTouchStart, handleTouchMove]);

  /* Derived values */
  const dangerIntensity =
    scrollProgress > 0.36 && scrollProgress < 0.68
      ? scrollProgress < 0.52
        ? Math.min(1, (scrollProgress - 0.36) / 0.14)
        : Math.max(0, 1 - (scrollProgress - 0.52) / 0.16)
      : 0;

  const guardianProgress =
    scrollProgress > 0.54 ? Math.min(1, (scrollProgress - 0.54) / 0.16) : 0;

  const showBlueprint = scrollProgress > 0.88;
  const showToys = scrollProgress > 0.26 && scrollProgress < 0.82;
  const showDustMotes = scrollProgress > 0.28 && scrollProgress < 0.82;

  return (
    <div
      ref={containerRef}
      style={{
        position: "fixed",
        inset: 0,
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        background: "#050818",
        cursor: "none",
      }}
    >
      {/* Global CSS keyframes */}
      <style>{`
        @keyframes spin  { to { transform: rotate(360deg); } }
        @keyframes pulse { 0%,100% { opacity: 0.3; } 50% { opacity: 0.7; } }
        @import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;1,300;1,400&display=swap');
      `}</style>

      <Suspense fallback={<Loader />}>
        <Canvas
          shadows
          dpr={Math.min(window.devicePixelRatio, 1.5)}
          gl={{
            antialias: true,
            toneMapping: THREE.ACESFilmicToneMapping,
            toneMappingExposure: 0.95,
          }}
          camera={{ fov: 50, near: 0.05, far: 200 }}
        >
          <FogController scrollProgress={scrollProgress} />
          <SceneLighting scrollProgress={scrollProgress} />
          <CameraManager scrollProgress={scrollProgress} />
          <Ground />

          {/* Phase 0: Starry sky */}
          <StarrySky scrollProgress={scrollProgress} />

          {/* Main scene objects */}
          <HouseComplete scrollProgress={scrollProgress} />

          <BabyCharacter scrollProgress={scrollProgress} position={[0, 0, 0]} />

          <Toys visible={showToys} />

          <HazardTable
            dangerIntensity={dangerIntensity}
            position={[0.8, 0, -0.3]}
          />

          <GuardianParticles
            progress={guardianProgress}
            position={[0.4, 0, 0.1]}
          />

          <DustMotes visible={showDustMotes} />

          {/* Post-processing */}
          <PostProcessingEffects scrollProgress={scrollProgress} />
        </Canvas>
      </Suspense>

      {/* Audio */}
      <AudioEngine scrollProgress={scrollProgress} />

      {/* 2D Overlays */}
      <PixieDustCursor />
      <StoryOverlay scrollProgress={scrollProgress} />
      <ScrollHUD progress={scrollProgress} />
      <BlueprintOverlay visible={showBlueprint} />
    </div>
  );
}

/**
 * ModelDiagnostic — Inspect all GLB models: bounding boxes, mesh names, sizes.
 * This is a temporary dev-only component for calibration.
 */
import { useEffect, useState } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, useGLTF, Grid } from '@react-three/drei';
import * as THREE from 'three';

interface ModelInfo {
  name: string;
  url: string;
  rawSize: { w: number; h: number; d: number };
  rawMin: { x: number; y: number; z: number };
  rawMax: { x: number; y: number; z: number };
  rawCenter: { x: number; y: number; z: number };
  meshNames: string[];
  meshCount: number;
  materialCount: number;
  vertexCount: number;
}

const MODEL_URLS = [
  '/models/house_complete.glb',
  '/models/room.glb',
  '/models/play_toys_animated.glb',
  '/models/sit_to_stand_animated.glb',
  '/models/walk_animated.glb',
  '/models/car_toy.glb',
  '/models/dog_toy.glb',
  '/models/seal_toys.glb',
  '/models/table_hazard.glb',
];

function ModelInspector({ url, onInfo }: { url: string; onInfo: (info: ModelInfo) => void }) {
  const { scene, animations } = useGLTF(url);

  useEffect(() => {
    const box = new THREE.Box3().setFromObject(scene);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    const meshNames: string[] = [];
    let meshCount = 0;
    let vertexCount = 0;
    const materials = new Set<string>();

    scene.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        meshCount++;
        meshNames.push(child.name || `unnamed_mesh_${meshCount}`);
        if (mesh.geometry) {
          const posAttr = mesh.geometry.getAttribute('position');
          if (posAttr) vertexCount += posAttr.count;
        }
        const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        mats.forEach((m) => materials.add(m.name || 'unnamed'));
      }
    });

    const info: ModelInfo = {
      name: url.split('/').pop() || url,
      url,
      rawSize: { w: +size.x.toFixed(3), h: +size.y.toFixed(3), d: +size.z.toFixed(3) },
      rawMin: { x: +box.min.x.toFixed(3), y: +box.min.y.toFixed(3), z: +box.min.z.toFixed(3) },
      rawMax: { x: +box.max.x.toFixed(3), y: +box.max.y.toFixed(3), z: +box.max.z.toFixed(3) },
      rawCenter: { x: +center.x.toFixed(3), y: +center.y.toFixed(3), z: +center.z.toFixed(3) },
      meshNames,
      meshCount,
      materialCount: materials.size,
      vertexCount,
    };

    console.log(`[ModelDiagnostic] ${info.name}:`, info);
    console.log(`  Animations: ${animations.length}`, animations.map(a => a.name));
    onInfo(info);
  }, [scene, animations, url, onInfo]);

  return null;
}

export default function ModelDiagnostic() {
  const [results, setResults] = useState<ModelInfo[]>([]);
  const [loaded, setLoaded] = useState(0);

  const handleInfo = (info: ModelInfo) => {
    setResults((prev) => {
      const existing = prev.findIndex((r) => r.url === info.url);
      if (existing >= 0) {
        const next = [...prev];
        next[existing] = info;
        return next;
      }
      return [...prev, info];
    });
    setLoaded((p) => p + 1);
  };

  return (
    <div style={{ position: 'fixed', inset: 0, background: '#0a0a14', color: '#fff', fontFamily: 'monospace', fontSize: 12, zIndex: 9999 }}>
      {/* Hidden Canvas to load models */}
      <Canvas style={{ position: 'absolute', width: 1, height: 1, opacity: 0 }}>
        {MODEL_URLS.map((url) => (
          <ModelInspector key={url} url={url} onInfo={handleInfo} />
        ))}
      </Canvas>

      <div style={{ padding: 20, overflow: 'auto', height: '100vh' }}>
        <h1 style={{ color: '#ffe4a0', fontSize: 18, marginBottom: 12 }}>
          🔍 Model Diagnostic ({loaded}/{MODEL_URLS.length} loaded)
        </h1>

        {results.length === 0 && <p style={{ color: '#888' }}>Loading models...</p>}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(420px, 1fr))', gap: 12 }}>
          {results.map((r) => (
            <div key={r.url} style={{
              background: 'rgba(255,255,255,0.05)',
              border: '1px solid rgba(255,255,255,0.1)',
              borderRadius: 8, padding: 14,
            }}>
              <div style={{ color: '#78dcd2', fontWeight: 'bold', fontSize: 14, marginBottom: 6 }}>
                📦 {r.name}
              </div>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <tbody>
                  <tr><td style={tdStyle}>Raw Size</td><td style={tdVal}>W={r.rawSize.w} H={r.rawSize.h} D={r.rawSize.d}</td></tr>
                  <tr><td style={tdStyle}>Raw Min</td><td style={tdVal}>({r.rawMin.x}, {r.rawMin.y}, {r.rawMin.z})</td></tr>
                  <tr><td style={tdStyle}>Raw Max</td><td style={tdVal}>({r.rawMax.x}, {r.rawMax.y}, {r.rawMax.z})</td></tr>
                  <tr><td style={tdStyle}>Raw Center</td><td style={tdVal}>({r.rawCenter.x}, {r.rawCenter.y}, {r.rawCenter.z})</td></tr>
                  <tr><td style={tdStyle}>Meshes</td><td style={tdVal}>{r.meshCount} meshes, {r.materialCount} materials</td></tr>
                  <tr><td style={tdStyle}>Vertices</td><td style={tdVal}>{r.vertexCount.toLocaleString()}</td></tr>
                  <tr><td style={tdStyle}>Mesh Names</td><td style={{ ...tdVal, maxHeight: 80, overflow: 'auto' }}>
                    {r.meshNames.map((n, i) => (
                      <span key={i} style={{
                        display: 'inline-block',
                        background: 'rgba(120,220,210,0.15)',
                        border: '1px solid rgba(120,220,210,0.2)',
                        borderRadius: 4, padding: '1px 6px', margin: '1px 2px',
                        fontSize: 11,
                      }}>{n}</span>
                    ))}
                  </td></tr>
                </tbody>
              </table>
            </div>
          ))}
        </div>

        {results.length > 0 && (
          <div style={{ marginTop: 20, padding: 14, background: 'rgba(255,228,160,0.08)', border: '1px solid rgba(255,228,160,0.2)', borderRadius: 8 }}>
            <h3 style={{ color: '#ffe4a0', marginBottom: 8 }}>📐 Scale Calculations</h3>
            {results.map((r) => {
              const targetH = r.name.includes('house') ? 3.5 : r.name.includes('room') ? 3.0 : r.name.includes('play') || r.name.includes('sit') || r.name.includes('walk') ? 0.5 : r.name.includes('table') ? 0.55 : 0.1;
              const scale = +(targetH / r.rawSize.h).toFixed(6);
              const worldW = +(r.rawSize.w * scale).toFixed(2);
              const worldH = +(r.rawSize.h * scale).toFixed(2);
              const worldD = +(r.rawSize.d * scale).toFixed(2);
              const floorOffset = +(-r.rawMin.y * scale).toFixed(4);
              return (
                <div key={r.url} style={{ marginBottom: 6, padding: '4px 0', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                  <span style={{ color: '#78dcd2' }}>{r.name}</span>: target H={targetH} → scale={scale} → world [{worldW} × {worldH} × {worldD}] floorOffset=+{floorOffset}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

const tdStyle: React.CSSProperties = { color: '#aaa', padding: '2px 8px 2px 0', verticalAlign: 'top', whiteSpace: 'nowrap' };
const tdVal: React.CSSProperties = { color: '#e0e0e0', padding: '2px 0' };

import React, { useState, useRef, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import AuthLayout from "../components/AuthLayout";

type Step = "email" | "otp" | "newPassword";

const ForgotPassword = () => {
  const navigate = useNavigate();
  const [step, setStep] = useState<Step>("email");

  const [email, setEmail] = useState("");
  const [otp, setOtp] = useState(["", "", "", ""]);
  const [timeLeft, setTimeLeft] = useState(300);
  const [canResend, setCanResend] = useState(false);
  const otpRefs = [
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
  ];

  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (step !== "otp") return;
    setTimeLeft(300);
    setCanResend(false);
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) { clearInterval(timer); setCanResend(true); return 0; }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [step]);

  const fmt = (s: number) =>
    `${Math.floor(s / 60).toString().padStart(2, "0")}:${(s % 60).toString().padStart(2, "0")}`;

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(""); setLoading(true);
    try {
      const res = await axios.post("/api/auth/forgotpassword", { email });
      if (res.data.success) { setStep("otp"); setMessage("OTP sent to your email!"); }
    } catch (err: any) {
      setError(err.response?.data?.error || "No account found with that email.");
    } finally { setLoading(false); }
  };

  const handleResend = async () => {
    setError(""); setOtp(["", "", "", ""]); setLoading(true);
    try {
      await axios.post("/api/auth/forgotpassword", { email });
      setCanResend(false);
      setStep("email");
      setTimeout(() => setStep("otp"), 10);
      setMessage("New OTP sent!");
    } catch { setError("Failed to resend OTP."); }
    finally { setLoading(false); }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    const code = otp.join("");
    if (code.length !== 4) { setError("Please enter all 4 digits."); return; }
    setLoading(true);
    try {
      const res = await axios.post("/api/auth/verifyotp", { email, otp: code });
      if (res.data.success) { setStep("newPassword"); setMessage(""); }
    } catch (err: any) {
      setError(err.response?.data?.error || "Invalid or expired OTP.");
    } finally { setLoading(false); }
  };

  const handleResetPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (newPassword !== confirmPassword) { setError("Passwords do not match!"); return; }
    if (newPassword.length < 6) { setError("Password must be at least 6 characters!"); return; }
    setLoading(true);
    try {
      const res = await axios.post("/api/auth/resetpassword-otp", { email, password: newPassword });
      if (res.data.success) {
        setMessage("Password reset! Redirecting…");
        setTimeout(() => navigate("/login"), 2000);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || "Failed to reset password.");
    } finally { setLoading(false); }
  };

  const handleOtpChange = (i: number, val: string) => {
    if (!/^\d*$/.test(val)) return;
    const next = [...otp]; next[i] = val.slice(-1); setOtp(next);
    if (val && i < 3) otpRefs[i + 1].current?.focus();
  };
  const handleOtpKey = (i: number, e: React.KeyboardEvent) => {
    if (e.key === "Backspace" && !otp[i] && i > 0) otpRefs[i - 1].current?.focus();
  };
  const handlePaste = (e: React.ClipboardEvent) => {
    const p = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 4);
    if (p.length === 4) { setOtp(p.split("")); otpRefs[3].current?.focus(); }
    e.preventDefault();
  };

  const stepIdx = step === "email" ? 0 : step === "otp" ? 1 : 2;
  const steps = ["Email", "Verify", "Reset"];

  return (
    <AuthLayout title="Reset password" subtitle="Follow the steps to recover your account" icon="🔐">

      {/* Step indicator */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 20 }}>
        {steps.map((label, i) => (
          <React.Fragment key={label}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
              <div style={{
                width: 28, height: 28, borderRadius: "50%",
                display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: "0.72rem", fontWeight: 800,
                background: i < stepIdx ? "#86efac" : i === stepIdx ? "linear-gradient(135deg,#818cf8,#a78bfa)" : "#f3f4f6",
                color: i <= stepIdx ? "white" : "#9ca3af",
                boxShadow: i === stepIdx ? "0 2px 8px rgba(139,92,246,0.35)" : "none",
                transform: i === stepIdx ? "scale(1.1)" : "scale(1)",
                transition: "all 0.25s",
              }}>
                {i < stepIdx ? "✓" : i + 1}
              </div>
              <span style={{
                fontSize: "0.65rem", fontWeight: 700,
                color: i === stepIdx ? "#818cf8" : "#d1d5db",
              }}>{label}</span>
            </div>
            {i < 2 && (
              <div style={{
                width: 36, height: 2, borderRadius: 2, margin: "0 4px", marginBottom: 16,
                background: i < stepIdx ? "#86efac" : "#f3f4f6",
                transition: "background 0.3s",
              }} />
            )}
          </React.Fragment>
        ))}
      </div>

      {/* Alerts */}
      {error && (
        <div style={{ background:"#fef2f2", border:"1.5px solid #fca5a5", color:"#dc2626", borderRadius:10, padding:"8px 12px", fontSize:"0.78rem", fontWeight:700, textAlign:"center", marginBottom:12 }}>
          {error}
        </div>
      )}
      {message && (
        <div style={{ background:"#f0fdf4", border:"1.5px solid #86efac", color:"#16a34a", borderRadius:10, padding:"8px 12px", fontSize:"0.78rem", fontWeight:700, textAlign:"center", marginBottom:12 }}>
          {message}
        </div>
      )}

      {/* STEP 1 */}
      {step === "email" && (
        <form onSubmit={handleSendOtp} className="space-y-3">
          <div>
            <label style={labelStyle}>Your Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)}
              required placeholder="name@example.com" className="auth-input" />
          </div>
          <div style={{ paddingTop: 4 }}>
            <button type="submit" disabled={loading} className="auth-btn">
              {loading ? "Sending…" : "Send OTP 📨"}
            </button>
          </div>
        </form>
      )}

      {/* STEP 2 */}
      {step === "otp" && (
        <form onSubmit={handleVerifyOtp} className="space-y-4">
          <p style={{ textAlign:"center", fontSize:"0.78rem", color:"#6b7280", fontWeight:600, margin:0 }}>
            Code sent to <strong style={{ color:"#818cf8" }}>{email}</strong>
          </p>

          {/* OTP boxes */}
          <div style={{ display:"flex", justifyContent:"center", gap:10 }}>
            {otp.map((digit, i) => (
              <input key={i} ref={otpRefs[i]}
                type="text" inputMode="numeric" maxLength={1} value={digit}
                onChange={(e) => handleOtpChange(i, e.target.value)}
                onKeyDown={(e) => handleOtpKey(i, e)}
                onPaste={i === 0 ? handlePaste : undefined}
                style={{
                  width: 52, height: 56, textAlign:"center",
                  fontSize: "1.5rem", fontWeight: 900,
                  borderRadius: 14,
                  border: digit ? "2px solid #a78bfa" : "2px solid #e5e7eb",
                  background: digit ? "rgba(167,139,250,0.08)" : "rgba(249,250,251,0.9)",
                  color: "#2d2d4a", outline: "none",
                  boxShadow: digit ? "0 0 0 3px rgba(167,139,250,0.15)" : "none",
                  transition: "all 0.15s",
                }}
              />
            ))}
          </div>

          {/* Timer */}
          <p style={{ textAlign:"center", fontSize:"0.75rem", color:"#9ca3af", fontWeight:600, margin:0 }}>
            {!canResend ? (
              <>Expires in{" "}
                <span style={{ fontWeight:800, color: timeLeft < 60 ? "#ef4444" : "#818cf8" }}>
                  {fmt(timeLeft)}
                </span>
              </>
            ) : (
              <>Code expired.{" "}
                <button type="button" onClick={handleResend} disabled={loading}
                  style={{ color:"#818cf8", fontWeight:800, background:"none", border:"none", cursor:"pointer", padding:0 }}>
                  Resend
                </button>
              </>
            )}
          </p>

          <button type="submit" disabled={loading || otp.join("").length !== 4} className="auth-btn">
            {loading ? "Verifying…" : "Verify Code ✅"}
          </button>
        </form>
      )}

      {/* STEP 3 */}
      {step === "newPassword" && (
        <form onSubmit={handleResetPassword} className="space-y-3">
          <p style={{ textAlign:"center", fontSize:"0.78rem", color:"#16a34a", fontWeight:700, margin:0 }}>
            ✅ Identity verified — set your new password
          </p>
          <div>
            <label style={labelStyle}>New Password</label>
            <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)}
              required minLength={6} placeholder="Min 6 characters" className="auth-input" />
          </div>
          <div>
            <label style={labelStyle}>Confirm Password</label>
            <input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
              required minLength={6} placeholder="••••••••" className="auth-input" />
          </div>
          <div style={{ paddingTop: 4 }}>
            <button type="submit" disabled={loading} className="auth-btn">
              {loading ? "Updating…" : "Reset Password 🚀"}
            </button>
          </div>
        </form>
      )}

      <div style={{ marginTop: 20, textAlign:"center", fontSize:"0.78rem", color:"#9ca3af", fontWeight:600 }}>
        Remembered it?{" "}
        <Link to="/login" style={{ color:"#818cf8", fontWeight:700, textDecoration:"none" }}>Sign in</Link>
      </div>
    </AuthLayout>
  );
};

const labelStyle: React.CSSProperties = {
  display: "block",
  fontSize: "0.72rem",
  fontWeight: 700,
  color: "#6b7280",
  textTransform: "uppercase",
  letterSpacing: "0.06em",
  marginBottom: 5,
};

export default ForgotPassword;

