                  </div>
                  <div className="text-xs font-bold text-yellow-700 mt-0.5">
                    👀 Caution Zones
                  </div>
                </div>
                <div className="rounded-xl bg-orange-50 border-2 border-orange-200 p-3 text-center">
                  <div className="text-2xl font-black text-orange-600">
